-- Seed the Bishop's Youth Excellence Award templates from the award guide.
-- These templates are shared by Young Men and Young Women; local leaders can
-- adapt the measurable details for a youth's circumstances.

with seed_actor as (
  select id
  from public.profiles
  where role in ('administrator', 'bishop')
  order by case when role = 'administrator' then 0 else 1 end, created_at
  limit 1
), seed_templates (id, title, summary, reflection_prompt, difficulty, category, duration_days) as (
  values
    ('8a100001-3a10-4f10-a001-000000000001'::uuid, 'Learn - Physical 1: Become a Safe and Capable Swimmer', 'Become a safe and capable swimmer while building courage, discipline, preparedness, stewardship, and service. Complete the requirements in a safe swimming area under qualified supervision.', 'How did this goal develop courage, preparedness, stewardship, or your ability to serve someone else?', 'hard'::public.goal_difficulty, 'physical'::public.goal_category, 30),
    ('8a100002-3a10-4f10-a002-000000000002'::uuid, 'Learn - Physical 2: Build a Healthy-Habit Routine', 'Build a four-week exercise and wellness routine that develops self-control, consistency, gratitude, and stewardship of the body.', 'How did this routine affect your stewardship of your body and your ability to serve God and others?', 'medium'::public.goal_difficulty, 'physical'::public.goal_category, 28),
    ('8a100003-3a10-4f10-a003-000000000003'::uuid, 'Learn - Intellectual 1: Learn a New Skill', 'Choose and practice a new skill such as cooking, sewing, woodworking, coding, music, art, photography, gardening, mechanics, or another meaningful skill.', 'How did patience and practice help you improve, and how can you continue developing this skill?', 'medium'::public.goal_difficulty, 'intellectual'::public.goal_category, 30),
    ('8a100004-3a10-4f10-a004-000000000004'::uuid, 'Learn - Intellectual 2: Learn Basic Life Skills', 'Complete at least three practical life-skill challenges that develop responsibility, independence, work, and wise stewardship.', 'How can dependable work and practical skills bless your family and increase your independence?', 'medium'::public.goal_difficulty, 'intellectual'::public.goal_category, 30),
    ('8a100005-3a10-4f10-a005-000000000005'::uuid, 'Learn - Spiritual 1: Learn About Jesus Christ', 'Study accounts of Jesus Christ, identify His attributes, practice one attribute, and share what you learned with someone you trust.', 'What did you learn about the Savior, and how did practicing one of His attributes change you?', 'medium'::public.goal_difficulty, 'spiritual'::public.goal_category, 30),
    ('8a100006-3a10-4f10-a006-000000000006'::uuid, 'Learn - Spiritual 2: Establish a Personal Worship Habit', 'Build a regular habit of prayer, scripture study, devotional participation, and recording spiritual impressions.', 'How did regular worship affect your thoughts, choices, and relationship with Jesus Christ?', 'medium'::public.goal_difficulty, 'spiritual'::public.goal_category, 30),
    ('8a100007-3a10-4f10-a007-000000000007'::uuid, 'Learn - Social 1: Include and Strengthen Others', 'Practice charity, kindness, awareness, and belonging by learning about others, including people who may feel left out, and completing quiet acts of kindness.', 'How did the Savior help people feel seen and valued, and what did you learn by trying to do the same?', 'medium'::public.goal_difficulty, 'social'::public.goal_category, 30),
    ('8a100008-3a10-4f10-a008-000000000008'::uuid, 'Learn - Social 2: Become a Peacemaker at Home', 'Strengthen a family relationship through patience, forgiveness, humility, listening, helpful action, and calm conflict resolution.', 'What did you learn about being a peacemaker, and how will you continue strengthening this relationship?', 'medium'::public.goal_difficulty, 'social'::public.goal_category, 30),

    ('8a100009-3a10-4f10-a009-000000000009'::uuid, 'Live - Physical 1: Develop Water Endurance and Emergency Skills', 'Develop water endurance, rescue awareness, and introductory first-aid or CPR knowledge under qualified supervision.', 'How did this goal increase your preparedness, confidence, courage, or ability to serve safely?', 'hard'::public.goal_difficulty, 'physical'::public.goal_category, 56),
    ('8a100010-3a10-4f10-a010-000000000010'::uuid, 'Live - Physical 2: Follow a Personal Fitness Program', 'Create and follow an eight-week fitness program focused on health, strength, endurance, mobility, recovery, and consistency rather than appearance or weight.', 'What helped you continue when motivation was low, and what healthy habit will you keep?', 'hard'::public.goal_difficulty, 'physical'::public.goal_category, 56),
    ('8a100011-3a10-4f10-a011-000000000011'::uuid, 'Live - Intellectual 1: Explore Education and Careers', 'Research careers, trades, or educational paths, interview adults, identify useful strengths and skills, and present what you learned.', 'How can meaningful work allow you to provide for and serve others?', 'medium'::public.goal_difficulty, 'intellectual'::public.goal_category, 42),
    ('8a100012-3a10-4f10-a012-000000000012'::uuid, 'Live - Intellectual 2: Practice Financial and Household Responsibility', 'Practice budgeting, comparing costs, meal planning, cooking, maintenance, and wise stewardship of household resources.', 'What financial or household habit will you continue, and how does it show stewardship and self-reliance?', 'hard'::public.goal_difficulty, 'intellectual'::public.goal_category, 30),
    ('8a100013-3a10-4f10-a013-000000000013'::uuid, 'Live - Spiritual 1: Learn to Seek Personal Revelation', 'Seek guidance through scripture study, prayer, recording impressions, acting on good promptings, and discussing appropriate learning with trusted adults.', 'What did you learn about recognizing the Holy Ghost and receiving revelation gradually?', 'hard'::public.goal_difficulty, 'spiritual'::public.goal_category, 42),
    ('8a100014-3a10-4f10-a014-000000000014'::uuid, 'Live - Spiritual 2: Participate in Temple and Family History Work', 'Participate in temple preparation, temple attendance when circumstances and worthiness permit, family history, indexing, or an equivalent family-history project.', 'What did temple and family-history service teach you about covenants, Jesus Christ, and gathering Israel?', 'medium'::public.goal_difficulty, 'spiritual'::public.goal_category, 30),
    ('8a100015-3a10-4f10-a015-000000000015'::uuid, 'Live - Social 1: Improve Communication and Resolve Conflict', 'Practice active listening, respectful communication, feedback, honest conversation, apology, restitution, and peaceful conflict resolution.', 'How did humility improve a relationship or help you communicate more like Jesus Christ?', 'hard'::public.goal_difficulty, 'social'::public.goal_category, 42),
    ('8a100016-3a10-4f10-a016-000000000016'::uuid, 'Live - Social 2: Participate in Meaningful Team Service', 'Identify a real need, help plan a project, complete meaningful service with others, fulfill responsibilities, and evaluate the result.', 'How did service change the way you saw another person, and what would you improve next time?', 'medium'::public.goal_difficulty, 'social'::public.goal_category, 42),

    ('8a100017-3a10-4f10-a017-000000000017'::uuid, 'Lead - Physical 1: Become a Water-Safety Leader', 'Develop advanced water endurance, rescue, emergency-response, and teaching skills while learning the responsibilities of a leader around water.', 'What did you learn about protecting others and leading responsibly around water?', 'hard'::public.goal_difficulty, 'physical'::public.goal_category, 84),
    ('8a100018-3a10-4f10-a018-000000000018'::uuid, 'Lead - Physical 2: Lead Through Personal Fitness', 'Follow a balanced 10- to 12-week fitness plan and lead age-appropriate activities while encouraging others without criticizing appearance or ability.', 'How did you lead through example, and what did you learn about encouragement and perseverance?', 'hard'::public.goal_difficulty, 'physical'::public.goal_category, 84),
    ('8a100019-3a10-4f10-a019-000000000019'::uuid, 'Lead - Intellectual 1: Complete a Capstone Skill or Project', 'Plan and complete a meaningful capstone skill or project that demonstrates excellence, creativity, patience, wisdom, and sustained work.', 'How did diligence and excellence help you honor God and serve others through this project?', 'hard'::public.goal_difficulty, 'intellectual'::public.goal_category, 84),
    ('8a100020-3a10-4f10-a020-000000000020'::uuid, 'Lead - Intellectual 2: Create a Personal Life-Launch Plan', 'Prepare for adult responsibilities by developing a resume, practicing applications and interviews, learning personal finance, identifying mentors, and setting preparation goals.', 'How does preparation increase your ability to serve God, family, and community?', 'hard'::public.goal_difficulty, 'intellectual'::public.goal_category, 84),
    ('8a100021-3a10-4f10-a021-000000000021'::uuid, 'Lead - Spiritual 1: Study, Teach, and Testify', 'Study a gospel doctrine, prepare and teach a lesson or devotional, invite participation, bear testimony, and seek feedback.', 'What did you learn about teaching by the Spirit and testifying of Jesus Christ?', 'hard'::public.goal_difficulty, 'spiritual'::public.goal_category, 56),
    ('8a100022-3a10-4f10-a022-000000000022'::uuid, 'Lead - Spiritual 2: Lead a Christlike Discipleship Effort', 'Create and follow an eight-week discipleship plan with prayer, scripture study, Sabbath worship, service, reflection, and an invitation to participate.', 'How did your relationship with Jesus Christ change through this effort, and which habit will you continue?', 'hard'::public.goal_difficulty, 'spiritual'::public.goal_category, 56),
    ('8a100023-3a10-4f10-a023-000000000023'::uuid, 'Lead - Social 1: Mentor and Strengthen a Younger Youth', 'With parent and leader awareness, encourage and support a younger youth in appropriate, observable settings while practicing compassion, patience, and individual ministry.', 'What did you learn about seeing and loving individuals as Christ does?', 'hard'::public.goal_difficulty, 'social'::public.goal_category, 56),
    ('8a100024-3a10-4f10-a024-000000000024'::uuid, 'Lead - Social 2: Plan and Lead a Team Project', 'Counsel with others, plan and lead a meaningful activity or service project, communicate responsibilities, adapt when needed, and evaluate the result.', 'What is the difference between controlling people and serving as a leader?', 'hard'::public.goal_difficulty, 'social'::public.goal_category, 56)
)
insert into public.goal_templates (
  id, title, summary, reflection_prompt, points, difficulty, category, duration_days,
  organization, created_by, ward_id, template_approved, template_approved_by, template_approved_at
)
select
  seed_templates.id,
  seed_templates.title,
  seed_templates.summary,
  seed_templates.reflection_prompt,
  0,
  seed_templates.difficulty,
  seed_templates.category,
  seed_templates.duration_days,
  'all'::public.organization_type,
  seed_actor.id,
  null,
  true,
  seed_actor.id,
  now()
from seed_templates
cross join seed_actor
on conflict (id) do update
set title = excluded.title,
    summary = excluded.summary,
    reflection_prompt = excluded.reflection_prompt,
    difficulty = excluded.difficulty,
    category = excluded.category,
    duration_days = excluded.duration_days,
    organization = excluded.organization,
    template_approved = true,
    template_approved_by = excluded.template_approved_by,
    template_approved_at = coalesce(public.goal_templates.template_approved_at, excluded.template_approved_at);

delete from public.template_checklist_items
where template_id between '8a100001-3a10-4f10-a001-000000000001'::uuid and '8a100024-3a10-4f10-a024-000000000024'::uuid;

